<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Accessor\ConsentPurposeTitleAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ConsentPurposeTitleAccessor trait.
 *
 * Covers null default, string/VO assignment via withTitle,
 * getTitle/title accessors, and isTitleChanged with/without original.
 */
class ConsentPurposeTitleAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTitle creates a new instance with the Title set
     * from a string value, and getTitle returns the primitive string.
     */
    public function testWithTitleFromString(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeTitleAccessorUnitTest();

        // Act
        $result = $holder->withTitle('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getTitle());
    }
    /**
     * Asserts that withtitle has access to the value object
     * from a string value, and getTitle returns the primitive string.
     */
    public function testWithTitleFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeTitleAccessorUnitTest();

        // Act
        $result = $holder->withTitle('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->title()->value());
    }
    public function testChangedTitle(): void
    {
        // Arrange
        $holder = new ImplWithConsentPurposeTitleAccessorUnitTest()->withTitle('one');
        $original = $holder->withTitle('one');
        $same = $holder->withTitle('one');
        $modified = $holder->withTitle('other');

        // Act
        $withSame = $original->isTitleChanged($same);
        $withDiferent = $original->isTitleChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithConsentPurposeTitleAccessorUnitTest
{
    use ConsentPurposeTitleAccessor;
}
